package com.bank.portfolio.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "holdings")
public class Holding {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "portfolio_id")
    private Portfolio portfolio;

    private String symbol;
    private int quantity;
    private BigDecimal avgPrice;

    protected Holding() { }
    public Holding(String symbol, int quantity, BigDecimal avgPrice) {
        this.symbol = symbol; this.quantity = quantity; this.avgPrice = avgPrice;
    }
    void setPortfolio(Portfolio p) { this.portfolio = p; }
    public String getSymbol() { return symbol; }
}
