package com.bank.portfolio.model;

import jakarta.persistence.*;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "portfolios")
public class Portfolio {
    @Id private String id;
    private String ownerId;
    private String name;

    // CascadeType.ALL  → persist/remove flow to holdings
    // orphanRemoval=true → removing a holding from this list DELETES its row
    @OneToMany(mappedBy = "portfolio", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Holding> holdings = new ArrayList<>();

    protected Portfolio() { }
    public Portfolio(String id, String ownerId, String name) {
        this.id = id; this.ownerId = ownerId; this.name = name;
    }

    // helper keeps both sides in sync
    public void addHolding(Holding h) { holdings.add(h); h.setPortfolio(this); }
    public void sellOff(String symbol) {
        holdings.removeIf(h -> {           // removal from list → orphanRemoval DELETE
            boolean match = h.getSymbol().equals(symbol);
            if (match) h.setPortfolio(null);
            return match;
        });
    }
    public List<Holding> getHoldings() { return holdings; }
}
