package com.bank.portfolio.service;

import com.bank.portfolio.model.Portfolio;
import com.bank.portfolio.repository.PortfolioRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class PortfolioService {

    private final PortfolioRepository portfolioRepo;

    // CascadeType.ALL: deleting the portfolio cascades DELETE to all holdings
    @Transactional
    public void closePortfolio(String id) {
        Portfolio pf = portfolioRepo.findById(id).orElseThrow();
        portfolioRepo.delete(pf);  // cascade REMOVE → holdings deleted too
        log.info("Closed portfolio {} and cascaded delete to all holdings", id);
    }

    // orphanRemoval: selling a whole position removes it from the list → row deleted
    @Transactional
    public void sellEntirePosition(String portfolioId, String symbol) {
        Portfolio pf = portfolioRepo.findById(portfolioId).orElseThrow();
        pf.sellOff(symbol);  // removed from collection → orphanRemoval DELETEs that holding
        log.info("Sold entire {} position; orphaned holding deleted", symbol);
    }
}
